public void testRebalanceTablesSequentially() throws InterruptedException {
    ControllerConf conf = mock(ControllerConf.class);
    when(conf.isSegmentRelocatorRebalanceTablesSequentially()).thenReturn(true);
    SegmentRelocator relocator = new SegmentRelocator(mock(TableRebalanceManager.class), mock(PinotHelixResourceManager.class), mock(LeadControllerManager.class), conf, mock(ControllerMetrics.class), mock(ExecutorService.class), mock(HttpClientConnectionManager.class));
    int cnt = 10;
    Random random = new Random();
    for (int i = 0; i < cnt; i++) {
        relocator.putTableToWait("t_" + i);
    }
    for (int i = 0; i < cnt; i++) {
        relocator.putTableToWait("t_" + random.nextInt(cnt));
    }
    // All tables are tracked and no duplicate table names.
    Queue<String> waitingQueue = relocator.getWaitingQueue();
    assertEquals(waitingQueue.size(), cnt);
