        assertEquals(waitingQueue.size(), cnt - i);
        relocator.rebalanceWaitingTable(s -> tableName[0] = s);
        assertEquals(tableName[0], "t_" + i);
    }
    assertEquals(waitingQueue.size(), 0);
}

