    Set<String> segmentsYetToBeCommitted = realtimeSegmentManager.getSegmentsYetToBeCommitted("test", segmentsToCheck);
    assert ImmutableSet.of("s2", "s4", "s5").equals(segmentsYetToBeCommitted);
}

