    ImmutableSegmentImpl seg03 = createImmutableSegment("seg03", segDir03, segmentsTakenSnapshot, new ArrayList<>());
    // Some docs excluded due to deletes
    ThreadSafeMutableRoaringBitmap queryableDocIds03 = createDocIds(3, 7);
