public void testGetTaskCountsWithSingleStateFilter() {
    String taskType = "TestTask";
    String taskName1 = "Task_TestTask_12345";
    String taskName2 = "Task_TestTask_67890";
    TaskDriver taskDriver = mock(TaskDriver.class);
