/**
 * Mocks a {@link DimensionTableDataManager} which looks like:
 * TeamID (PK, str) | TeamName(str) | TeamName_MV(str[]) | TeamInteger(int) | TeamInteger_MV(int[]) | TeamFloat
 * (float) | ...
 *
 * All values are dynamically created to be variations of the primary key.
 * e.g.
 * lookupRowByPrimaryKey(['FOO']) -> (TeamID: 'foo', TeamName: 'teamName_for_foo', TeamInteger: hashCode(['foo']), ...
 */
private DimensionTableDataManager mockDataManager() {
    DimensionTableDataManager tableManager = mock(DimensionTableDataManager.class);
    when(tableManager.getPrimaryKeyColumns()).thenReturn(List.of("teamID"));
    when(tableManager.isPopulated()).thenReturn(true);
    when(tableManager.getColumnFieldSpec("teamID")).thenReturn(new DimensionFieldSpec("teamID", DataType.STRING, true));
    when(tableManager.getColumnFieldSpec("teamName")).thenReturn(new DimensionFieldSpec("teamName", DataType.STRING, true));
    when(tableManager.getColumnFieldSpec("teamName_MV")).thenReturn(new DimensionFieldSpec("teamName_MV", DataType.STRING, false));
    when(tableManager.getColumnFieldSpec("teamInteger")).thenReturn(new DimensionFieldSpec("teamInteger", DataType.INT, true));
    when(tableManager.getColumnFieldSpec("teamInteger_MV")).thenReturn(new DimensionFieldSpec("teamInteger_MV", DataType.INT, false));
    when(tableManager.getColumnFieldSpec("teamFloat")).thenReturn(new DimensionFieldSpec("teamFloat", DataType.FLOAT, true));
    when(tableManager.getColumnFieldSpec("teamFloat_MV")).thenReturn(new DimensionFieldSpec("teamFloat_MV", DataType.FLOAT, false));
    when(tableManager.getColumnFieldSpec("teamDouble")).thenReturn(new DimensionFieldSpec("teamDouble", DataType.DOUBLE, true));
    when(tableManager.getColumnFieldSpec("teamDouble_MV")).thenReturn(new DimensionFieldSpec("teamDouble_MV", DataType.DOUBLE, false));
    when(tableManager.getColumnFieldSpec("teamLong")).thenReturn(new DimensionFieldSpec("teamLong", DataType.LONG, true));
    when(tableManager.getColumnFieldSpec("teamLong_MV")).thenReturn(new DimensionFieldSpec("teamLong_MV", DataType.LONG, false));
    when(tableManager.getColumnFieldSpec("teamBytes")).thenReturn(new DimensionFieldSpec("teamNameBytes", DataType.BYTES, true));
    when(tableManager.lookupValue(any(PrimaryKey.class), any(String.class))).thenAnswer(invocation -> {
        PrimaryKey key = invocation.getArgument(0);
        String column = invocation.getArgument(1);
        switch(column) {
            case "teamName":
                return String.format("teamName_for_%s", key);
            case "teamName_MV":
                return new String[] { String.format("teamName_for_%s_1", key), String.format("teamName_for_%s_2", key) };
            case "teamInteger":
                return key.hashCode();
            case "teamInteger_MV":
                return new int[] { key.hashCode(), key.hashCode() };
            case "teamFloat":
                return (float) key.hashCode();
            case "teamFloat_MV":
                return new float[] { (float) key.hashCode(), (float) key.hashCode() };
            case "teamDouble":
                return (double) key.hashCode();
            case "teamDouble_MV":
                return new double[] { (double) key.hashCode(), (double) key.hashCode() };
            case "teamLong":
                return (long) key.hashCode();
            case "teamLong_MV":
                return new long[] { (long) key.hashCode(), (long) key.hashCode() };
            case "teamBytes":
                return String.format("teamBytes_for_%s", key).getBytes();
            default:
                throw new IllegalArgumentException("Unknown column: " + column);
        }
    });
    return tableManager;
}

