    DataSchema compositeSchema = new DataSchema(new String[] { "int_col", "string_col", "double_col" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.STRING, ColumnDataType.DOUBLE });
    _leftInput = new BlockListMultiStageOperator.Builder(compositeSchema).addRow(1, "Aa", // Has match in right
    1.0).addRow(2, null, // Null key - should be included
    2.0).addRow(3, "Cc", // No match in right
    3.0).buildWithEos();
    _rightInput = new BlockListMultiStageOperator.Builder(compositeSchema).addRow(1, "Aa", // Match for left row 1
    1.0).addRow(2, null, // Null key - should not match left null
    2.0).addRow(4, "Dd", // No match in left
    4.0).buildWithEos();
    DataSchema resultSchema = new DataSchema(new String[] { "int_col1", "string_col1", "double_col1" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.STRING, ColumnDataType.DOUBLE });
    // Composite key join on columns 1 and 2 (string_col and double_col)
    HashJoinOperator operator = getOperator(resultSchema, JoinRelType.ANTI, List.of(1, 2), List.of(1, 2), List.of());
    List<Object[]> resultRows = ((MseBlock.Data) operator.nextBlock()).asRowHeap().getRows();
    // Left rows with null keys and unmatched non-null keys should be returned
    assertEquals(resultRows.size(), 2);
    // Null key preserved
    assertTrue(containsRow(resultRows, new Object[] { 2, null, 2.0 }));
    // Unmatched preserved
    assertTrue(containsRow(resultRows, new Object[] { 3, "Cc", 3.0 }));
}

